// 02 - Critical sections: the kernel lock across cores, IRQ masking, nesting.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "smp_helpers.hpp"

using namespace os::rtos;
using namespace mtp_smp;

namespace
{
  constexpr unsigned cs_increments = 10000;
  volatile std::uint32_t g_cs_counter = 0;

  void*
  count_under_cs (void*)
  {
    for (unsigned i = 0; i < cs_increments; ++i)
      {
        interrupts::critical_section ics;
        const std::uint32_t value = g_cs_counter;
        asm volatile ("" ::: "memory");
        g_cs_counter = value + 1;
      }
    return nullptr;
  }

  volatile unsigned g_go = 0;
  volatile unsigned g_trying = 0;
  volatile unsigned g_entered = 0;

  void*
  enter_when_told (void*)
  {
    while (load (g_go) == 0)
      {
        mtp_board::cpu_relax ();
      }
    store (g_trying, 1u);
    {
      interrupts::critical_section ics;
      store (g_entered, 1u);
    }
    return nullptr;
  }

  volatile unsigned g_peer_ran = 0;

  void*
  run_when_told (void*)
  {
    while (load (g_go) == 0)
      {
        mtp_board::cpu_relax ();
      }
    store (g_peer_ran, 1u);
    return nullptr;
  }

  semaphore_binary* g_wake = nullptr;
  volatile unsigned g_high_ran = 0;

  void*
  high_on_core0 (void*)
  {
    (void)g_wake->wait ();
    store (g_high_ran, 1u);
    return nullptr;
  }
} // namespace

mt::static_suite suite_critical{
  "02 - Critical sections", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("interrupts::critical_section excludes every core", [] (auto& t) {
      g_cs_counter = 0;
      thread* threads[ncpu] = {};
      for (unsigned core = 0; core < ncpu; ++core)
        {
          threads[core] = spawn ("mtp-cs", count_under_cs, nullptr,
                                 static_cast<int> (core));
        }
      for (auto* th : threads)
        {
          finish (th);
        }
      t.expect (mt::eq (static_cast<std::uint32_t> (g_cs_counter),
                        static_cast<std::uint32_t> (ncpu * cs_increments)))
          << fmt ("%u increments under the kernel lock, none lost",
                  ncpu * cs_increments);
    });

    ts.test ("interrupts::critical_section masks, nests and restores",
             [] (auto& t) {
               const bool before = mtp_board::irqs_masked ();
               bool outer = false;
               bool inner = false;
               bool between = false;
               {
                 interrupts::critical_section a;
                 outer = mtp_board::irqs_masked ();
                 {
                   interrupts::critical_section b; // the kernel lock is recursive
                   inner = mtp_board::irqs_masked ();
                 }
                 between = mtp_board::irqs_masked ();
               }
               const bool after = mtp_board::irqs_masked ();
               t.expect (!before) << "the runner starts unmasked";
               t.expect (outer) << "masked in the outer section";
               t.expect (inner) << "masked in the nested section, no deadlock";
               t.expect (between) << "still masked after the nested one ends";
               t.expect (mt::eq (after, before)) << "restored after the outer one";
             });

    ts.test ("a core waits while another holds the kernel lock", [] (auto& t) {
      store (g_go, 0u);
      store (g_trying, 0u);
      store (g_entered, 0u);
      thread* th = spawn ("mtp-cs-wait", enter_when_told, nullptr, 1);
      sysclock.sleep_for (ms (5)); // let it start spinning on core 1
      bool tried = false;
      bool kept_out = true;
      {
        interrupts::critical_section ics;
        store (g_go, 1u);
        for (unsigned i = 0; i < 2000000 && !tried; ++i)
          {
            tried = load (g_trying) != 0;
          }
        busy_loop (200000); // core 1 is now spinning on the lock
        kept_out = load (g_entered) == 0;
      }
      const bool entered = wait_until (g_entered, ms (100));
      finish (th);
      t.expect (tried) << "core 1 reached the critical section";
      t.expect (kept_out) << "and did not enter while core 0 held it";
      t.expect (entered) << "it entered once core 0 left";
    });

    ts.test ("scheduler::critical_section is local to its core", [] (auto& t) {
      store (g_go, 0u);
      store (g_peer_ran, 0u);
      thread* th = spawn ("mtp-sched-peer", run_when_told, nullptr, 1);
      sysclock.sleep_for (ms (5));
      bool was_locked = false;
      bool progressed = false;
      {
        scheduler::critical_section scs;
        was_locked = scheduler::locked ();
        // If the scheduler lock were global, the thread on core 1 could not
        // run until this section ended, and the wait would time out.
        store (g_go, 1u);
        progressed = spin_until_bounded (g_peer_ran, 20000000);
      }
      const bool unlocked = !scheduler::locked ();
      finish (th);
      t.expect (was_locked) << "scheduler::locked () is true inside";
      t.expect (unlocked) << "and false after";
      t.expect (progressed) << "core 1 ran while core 0 held its scheduler lock";
    });

    ts.test ("scheduler::critical_section holds off switches on its core",
             [] (auto& t) {
               semaphore_binary wake{ "mtp-wake", 0 };
               g_wake = &wake;
               store (g_high_ran, 0u);
               thread* th = spawn ("mtp-high0", high_on_core0, nullptr, 0,
                                   thread::priority::above_normal);
               sysclock.sleep_for (ms (2)); // it blocks on the semaphore
               bool held_off = false;
               {
                 scheduler::critical_section scs;
                 (void)wake.post (); // ready, higher priority, same core
                 busy_loop (500000); // not the clock: it may stand still here
                 held_off = load (g_high_ran) == 0;
               }
               const bool ran = wait_until (g_high_ran, ms (100));
               finish (th);
               t.expect (held_off) << "the higher-priority thread waited for the unlock";
               t.expect (ran) << "and ran after it";
             });
  }
};
